<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useI18n } from 'vue-i18n';import { api } from '../api';import AppIcon from '../components/AppIcon.vue';import SpeakButton from '../components/SpeakButton.vue'
const {t,locale}=useI18n();const queue=ref<any[]>([]);const index=ref(0);const revealed=ref(false);const mode=ref<'recognition'|'production'>('production');const done=ref(0);const error=ref('');const loading=ref(true)
function current(item:any){return !item||item.interfaceLocale===String(locale.value)}
async function localize(item:any){return current(item)?item:api.post<any>(`/words/${item.id}/localize`,{interfaceLocale:String(locale.value)})}
onMounted(async()=>{try{const items=await api.get<any[]>('/reviews/due');if(items[0])items[0]=await localize(items[0]);queue.value=items}catch{error.value=t('common.operationFailed')}finally{loading.value=false}})
const word=computed(()=>queue.value[index.value])
// A word that comes back within this long is asked once more before the sitting ends.
const SOON=20*60_000
async function rate(rating:number){if(!word.value)return;error.value='';try{const next=index.value+1;if(queue.value[next])queue.value[next]=await localize(queue.value[next]);const result=await api.post<{dueAt:string;nextReview?:Record<number,number>|null}>(`/reviews/${word.value.id}`,{rating});if(result?.nextReview&&new Date(result.dueAt).getTime()-Date.now()<=SOON)queue.value.push({...word.value,nextReview:result.nextReview});done.value++;index.value++;revealed.value=false}catch{error.value=t('common.operationFailed')}}
/** When the word comes back after a rating, in the words of the interface language. Empty when the schedule is unknown. */
function nextIn(rating:number){const minutes=Number(word.value?.nextReview?.[rating]);if(!(minutes>0))return '';const days=minutes/1440;const [value,unit]=minutes<60?[minutes,'minute']:minutes<1440?[Math.round(minutes/60),'hour']:days<60?[Math.round(days),'day']:days<730?[Math.round(days/30),'month']:[Math.round(days/365),'year'];return new Intl.NumberFormat(String(locale.value),{style:'unit',unit,unitDisplay:'long'}).format(value)}
</script>
<template>
  <div class="page review-page">
    <header class="page-head"><h1>{{ t('review.title') }}</h1><div class="review-count"><b>{{ Math.max(0, queue.length - index) }}</b><span>{{ t('review.left') }}</span></div></header>
    <p v-if="error" class="load-error">{{ error }}</p>
    <div v-if="word" class="review-stage">
      <div class="mode-toggle"><button :class="{ active: mode === 'production' }" @click="mode = 'production'">{{ t('review.recall') }}</button><button :class="{ active: mode === 'recognition' }" @click="mode = 'recognition'">{{ t('review.recognize') }}</button></div>
      <div class="review-card card">
        <span class="badge">{{ word.language.toUpperCase() }} · {{ index + 1 }} / {{ queue.length }}</span>
        <template v-if="mode === 'production'"><p class="prompt-label">{{ t('review.recallPrompt') }}</p><blockquote>{{ word.source_sentence?.replace(new RegExp(word.term, 'ig'), '_____') || word.meaning }}</blockquote><small>{{ word.meaning }}</small></template>
        <template v-else><p class="prompt-label">{{ t('review.recognizePrompt') }}</p><h2>{{ word.term }}</h2><blockquote>{{ word.source_sentence }}</blockquote></template>
        <button v-if="!revealed" class="btn primary reveal" @click="revealed = true"><AppIcon name="spark" />{{ t('review.showAnswer') }}</button>
        <Transition name="answer"><div v-if="revealed" class="answer"><small>{{ t('review.answer') }}</small><div class="answer-title"><h2>{{ mode === 'production' ? word.term : word.meaning }}</h2><SpeakButton speech-id="review-term" :text="word.term" :language-code="word.language" /></div><div v-if="word.details?.senses?.[0]?.example" class="answer-example"><p :lang="word.language">{{ word.details.senses[0].example }}</p><SpeakButton speech-id="review-example" :text="word.details.senses[0].example" :language-code="word.language" compact /></div></div></Transition>
      </div>
      <div v-if="revealed" class="ratings"><button @click="rate(1)"><b>{{ t('review.again') }}</b><span>{{ t('review.tenMinutes') }}</span></button><button @click="rate(2)"><b>{{ t('review.hard') }}</b><span>{{ t('review.oneDay') }}</span></button><button @click="rate(3)"><b>{{ t('review.good') }}</b><span>{{ t('review.threeDays') }}</span></button><button @click="rate(4)"><b>{{ t('review.easy') }}</b><span>{{ t('review.longer') }}</span></button></div>
    </div>
    <div v-else-if="!loading&&!error" class="review-done card"><span><AppIcon name="check" :size="28" /></span><h2>{{ done ? t('review.done') : t('review.nothingDue') }}</h2><p>{{ t('review.doneBody') }}</p><RouterLink to="/words" class="btn">{{ t('review.back') }}</RouterLink></div>
  </div>
</template>
<style scoped>.review-page{max-width:880px}.review-count{text-align:right}.review-count b,.review-count span{display:block}.review-count b{font-size:27px;color:var(--green)}.review-count span{font-size:11px;letter-spacing:.1em;color:var(--muted)}.review-stage{max-width:650px;margin:auto}.mode-toggle{display:flex;justify-content:center;margin-bottom:13px}.mode-toggle button{height:31px;padding:0 13px;border:1px solid var(--line);background:transparent;color:var(--muted);font-size:11px}.mode-toggle button:first-child{border-radius:8px 0 0 8px}.mode-toggle button:last-child{border-radius:0 8px 8px 0}.mode-toggle button.active{background:var(--green);color:white;border-color:var(--green)}.review-card{min-height:390px;padding:32px;text-align:center;display:flex;flex-direction:column;align-items:center}.prompt-label{font-size:11px;letter-spacing:.13em;color:var(--muted);margin-top:70px}.review-card blockquote{font-size:19px;line-height:1.7;margin:14px auto;max-width:500px}.review-card>small{font-size:11px;color:var(--muted)}.review-card>h2{font-size:35px;margin:16px 0}.reveal{margin-top:auto}.answer{margin-top:auto;padding-top:22px;border-top:1px solid var(--line);width:100%}.answer small{font-size:11px;color:var(--green);letter-spacing:.1em}.answer-title{display:flex;align-items:center;justify-content:center;gap:7px}.answer h2{min-width:0;font-size:29px;margin:7px;overflow-wrap:anywhere}.answer-example{display:flex;align-items:center;justify-content:center;gap:5px}.answer p{min-width:0;font-size:11px;color:var(--muted)}.ratings{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:11px}.ratings button{height:56px;border:1px solid var(--line);border-radius:9px;background:var(--paper)}.ratings b,.ratings span{display:block}.ratings b{font-size:11px}.ratings span{font-size:11px;color:var(--muted);margin-top:4px}.ratings button:hover{border-color:var(--green);color:var(--green)}.review-done{padding:60px;text-align:center}.review-done>span{width:58px;height:58px;border-radius:50%;background:var(--lime);color:var(--green);display:grid;place-items:center;margin:auto}.review-done h2{margin:18px 0 7px}.review-done p{font-size:12px;color:var(--muted);margin-bottom:20px}.answer-enter-active{transition:.25s}.answer-enter-from{opacity:0;transform:translateY(7px)}@media(max-width:600px){.review-card{padding:22px;min-height:420px}.ratings{grid-template-columns:1fr 1fr}}</style>
<style scoped>
.review-page{max-width:920px}.review-count b{color:var(--blue)}.review-stage{max-width:720px}.mode-toggle{gap:5px}.mode-toggle button{height:34px;padding:0 15px;border:0;border-radius:999px!important}.mode-toggle button.active{background:var(--ink)}.review-card{min-height:460px;padding:34px;border-radius:30px}.prompt-label{margin-top:auto}.review-card blockquote{max-width:600px;font-family:'Songti SC',STSong,serif;font-size:28px;line-height:1.55}.review-card>h2{font-family:'Songti SC',STSong,serif}.reveal{height:46px;margin-top:auto;border-radius:999px}.answer{padding-top:24px}.answer small{color:var(--blue)}.answer h2{font-family:'Songti SC',STSong,serif;font-size:38px;font-weight:520}.ratings{gap:8px}.ratings button{height:62px;border:0;border-radius:14px;background:#e6e1d7}.ratings button:nth-child(2){background:#ead6cb}.ratings button:nth-child(3){background:#d9e4dc}.ratings button:nth-child(4){background:#d8dff0}.review-done{min-height:460px;border-radius:30px}
</style>
